// <diletta-button> — a INSTÂNCIA WEB de `design-system-button`.
//
// A peça de referência da casa, e a mais usada do BackOffice (255 instâncias).
// A pintura das 192 combinações vem de pintura.g.js, gerado da tabela que o Dart
// mede no render — nenhuma cor está escrita aqui.
import { papeisDe, estiloDa, eixo } from './base.js';

const SLUG = 'design-system-button';
const TYPE = ['primary', 'secondary', 'secondaryPrimary', 'white',
              'tertiary', 'tertiaryPrimary', 'secondaryWhite', 'tertiaryWhite'];
const SIZE = ['sm', 'md', 'lg'];
const STATE = ['normal', 'error'];
const INTERACAO = ['normal', 'hover', 'pressed', 'disabled'];

// Medido no _sizeSpec do Dart. A altura cedeu ao desenho em 21/08/2026 por decisão
// do dono: altura de botão não é detalhe de uma peça, é o RITMO da tela.
const PORTE = {
  sm: { h: 28, px: 12, icone: 14 },
  md: { h: 36, px: 14, icone: 16 },
  lg: { h: 56, px: 16, icone: 18 },
};
const ALVO = 44;

class DilettaButton extends HTMLElement {
  static observedAttributes = ['type', 'size', 'state', 'interacao', 'rotulo', 'disabled', 'href'];

  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
  }

  connectedCallback() { this.render(); }
  attributeChangedCallback() { if (this.shadowRoot) this.render(); }

  /// A pintura de UMA interação, já em declarações CSS.
  regra(type, size, state, inter) {
    return estiloDa(papeisDe(SLUG, { Type: type, Size: size, State: state, Interacao: inter }));
  }

  render() {
    const type = eixo(this, 'type', TYPE, 'primary');
    const size = eixo(this, 'size', SIZE, 'lg');
    const state = eixo(this, 'state', STATE, 'normal');
    const g = PORTE[size];
    const off = this.hasAttribute('disabled');
    // `interacao` FORÇA um estado, como o `statusForcado` do Dart. Serve ao
    // catálogo; em uso real quem manda é o navegador.
    const forcada = INTERACAO.includes(this.getAttribute('interacao'))
      ? this.getAttribute('interacao') : null;

    // A INTERAÇÃO É DO NAVEGADOR, e não de atributo. Emitir uma regra por pseudo
    // classe mantém a pintura vindo da MEDIÇÃO e deixa o estado com quem o conhece
    // — teclado, ponteiro e toque incluídos. Forçar por atributo exigiria JS para
    // cada `mouseenter`, e erraria no foco por teclado.
    const base = this.regra(type, size, state, forcada || 'normal');
    const hover = this.regra(type, size, state, 'hover');
    const pressed = this.regra(type, size, state, 'pressed');
    const desligado = this.regra(type, size, state, 'disabled');

    const conteudo = `<slot name="lead"></slot><span class="rotulo">${
      this.getAttribute('rotulo') || ''}</span><slot name="trail"></slot>`;
    const href = this.getAttribute('href');
    const tag = href && !off ? 'a' : 'button';

    this.shadowRoot.innerHTML = `
      <style>
        /* O ALVO É MAIOR QUE O DESENHO no porte pequeno: 28 de botão dentro de 44
           de alvo. Mesmo arranjo do chip e do DilettaAlvoDeToque — crescer o botão
           até 44 mudaria o ritmo da tela, que é justamente o que a altura carrega.
           (Sem crase: isto mora num template literal.) */
        :host { display: inline-flex; align-items: center; min-height: ${ALVO}px; }
        .botao {
          box-sizing: border-box;
          height: ${g.h}px; padding: 0 ${g.px}px;
          display: inline-flex; align-items: center; justify-content: center; gap: 8px;
          border-width: 1px; border-style: solid; border-color: transparent;
          border-radius: 999px;
          font: inherit; text-decoration: none; cursor: pointer;
          ${base}
        }
        ${forcada ? '' : `.botao:hover:not(:disabled) { ${hover} }`}
        ${forcada ? '' : `.botao:active:not(:disabled) { ${pressed} }`}
        .botao:disabled, .botao[aria-disabled="true"] { ${desligado} cursor: default; }
        .botao:focus-visible { outline: 3px solid var(--cps-primary); outline-offset: 2px; }
        ::slotted(svg) { width: ${g.icone}px; height: ${g.icone}px; }
      </style>
      <${tag} class="botao" part="botao"
        ${tag === 'button' ? `type="button"${off ? ' disabled' : ''}`
                           : `href="${href.replace(/"/g, '&quot;')}"`}
        >${conteudo}</${tag}>`;
  }
}

customElements.define('diletta-button', DilettaButton);
export { DilettaButton, PORTE, ALVO };
